#!/usr/bin/env python3
"""Require the Linux emulator job's test inputs before tests can silently skip."""
import os
import sys

# Job mappings plus the keys and TLS/bastion settings generated by its setup steps.
REQUIRED_ENV = """
DRE_TEST_POSTGRES DRE_TEST_S3_ENDPOINT DRE_TEST_AZURITE_ENDPOINT DRE_TEST_GCS_ENDPOINT
DRE_TEST_SFTP DRE_TEST_FTP DRE_TEST_FTPS DRE_TEST_SMTP DRE_TEST_MAILPIT_API
DRE_TEST_BIGQUERY_EMULATOR DRE_TEST_CLICKHOUSE_HTTP DRE_TEST_CLICKHOUSE_NATIVE
DRE_TEST_SFTP_KEY DRE_TEST_SFTP_ECDSA_KEY DRE_TEST_SSH_BASTION DRE_TEST_SSH_KEY
DRE_TEST_POSTGRES_TLS DRE_TEST_POSTGRES_CA DRE_TEST_CLICKHOUSE_HTTPS
DRE_TEST_CLICKHOUSE_NATIVE_TLS DRE_TEST_CLICKHOUSE_CA
""".split()


def main():
    missing = [name for name in REQUIRED_ENV if not os.environ.get(name)]
    if missing:
        print(f"::error::Missing required emulator test environment: {', '.join(missing)}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
